import 'package:flutter/material.dart';
import 'package:widgetbook/widgetbook.dart';
import 'package:widgetbook_annotation/widgetbook_annotation.dart' as widgetbook;

// TODO: import your real app theme, e.g.
// import 'package:your_app/theme/app_theme.dart';

// Generated by: dart run build_runner build -d
import 'main.directories.g.dart';

void main() {
  runApp(const WidgetbookApp());
}

@widgetbook.App()
class WidgetbookApp extends StatelessWidget {
  const WidgetbookApp({super.key});

  @override
  Widget build(BuildContext context) {
    return Widgetbook.material(
      directories: directories,
      addons: [
        // Replace ThemeData.light()/dark() with your app's real themes so the
        // catalog shows components exactly as they look in the app.
        MaterialThemeAddon(
          themes: [
            WidgetbookTheme(name: 'Light', data: ThemeData.light()),
            WidgetbookTheme(name: 'Dark', data: ThemeData.dark()),
          ],
        ),
        // Order matters: viewport first, then alignment.
        ViewportAddon(Viewports.all),
        AlignmentAddon(),
      ],
    );
  }
}
